import{_ as d,o as a,c as r,a2 as i}from"./chunks/framework.Dh6DF7gt.js";const m=JSON.parse('{"title":"自动化场景","description":"以场景而不是设备为中心设计、测试和维护自动化规则。","frontmatter":{"title":"自动化场景","description":"以场景而不是设备为中心设计、测试和维护自动化规则。"},"headers":[],"relativePath":"implementation/automation.md","filePath":"implementation/automation.md","lastUpdated":1785488055000}'),e={name:"implementation/automation.md"};function l(o,t,n,h,s,g){return a(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="自动化场景" tabindex="-1">自动化场景 <a class="header-anchor" href="#自动化场景" aria-label="Permalink to &quot;自动化场景&quot;">​</a></h1><p>本页定义自动化规则的优先级、触发条件、恢复方式和验收标准。设备架构与逐房间点位见<a href="/ai-lab-smart-office/implementation/smart-office-plan">智能化总体方案</a>。</p><h2 id="控制优先级" tabindex="-1">控制优先级 <a class="header-anchor" href="#控制优先级" aria-label="Permalink to &quot;控制优先级&quot;">​</a></h2><p>当多条规则同时满足时，按以下顺序执行：</p><ol><li><strong>生命安全与设备保护</strong>：消防、应急、漏水、高温、电机互锁。</li><li><strong>现场手动操作</strong>：墙面开关、窗帘开/停/关、机房本地控制。</li><li><strong>显式场景</strong>：会议、演示、活动、清扫、加班。</li><li><strong>人员存在与环境规则</strong>：自动灯、自动遮阳、空调节能。</li><li><strong>时间表与优化规则</strong>：上班预热、下班节能、日光补偿。</li></ol><p>高优先级操作发生后，低优先级规则应暂停；不得出现“用户刚关灯，自动化立即重新开灯”的反复控制。</p><h2 id="核心场景" tabindex="-1">核心场景 <a class="header-anchor" href="#核心场景" aria-label="Permalink to &quot;核心场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>触发</th><th>动作</th><th>退出与回退</th></tr></thead><tbody><tr><td>工作日到达</td><td>首次有效人员存在且处于工作时段</td><td>按实际照度打开所在区域，不预先点亮全办公室</td><td>无人后按房间延时关闭</td></tr><tr><td>开放区工作</td><td>A大厅存在人员</td><td>靠窗/内侧灯组分别日光补偿，保持工作场景</td><td>手动调光覆盖 2 小时或直到区域无人</td></tr><tr><td>会议</td><td>预约开始、面板按键或会议室有人</td><td>基础照明、空调/新风进入会议状态</td><td>预约结束且无人后恢复节能状态</td></tr><tr><td>演示</td><td>会议面板“演示”</td><td>关闭窗帘，前区灯降低，屏幕侧灯关闭</td><td>再次按键或会议结束后恢复原状态</td></tr><tr><td>就餐</td><td>餐厅存在人员且处于就餐时段</td><td>开启主餐厅与取餐区灯光，按日光调节北侧临窗灯组</td><td>无人后进入清洁等待，再关闭</td></tr><tr><td>防眩光</td><td>有人、太阳位于对应朝向且眩光/热负荷达到条件</td><td>东/西侧窗帘分级关闭到预设位置</td><td>手动操作后暂停自动遮阳，超时后恢复</td></tr><tr><td>清扫</td><td>清扫面板、管理端或计划任务</td><td>指定区域全亮，暂时禁用无人关灯</td><td>到时提醒；确认结束或全区无人后退出</td></tr><tr><td>加班</td><td>正常下班后检测到人员并确认加班</td><td>只维持有人区域、通行路径和卫生间</td><td>最后人员离开后执行离场检查</td></tr><tr><td>夜间离场</td><td>全区无人达到设定时间</td><td>关闭普通照明、显示设备，窗帘到夜间位置</td><td>入口或授权区域重新检测到人员时局部恢复</td></tr><tr><td>环境告警</td><td>CO₂、温湿度、漏水或机房状态越限</td><td>联动新风或发送分级告警</td><td>指标恢复并人工确认，关键告警不得自动静默</td></tr></tbody></table><h2 id="分区初始参数" tabindex="-1">分区初始参数 <a class="header-anchor" href="#分区初始参数" aria-label="Permalink to &quot;分区初始参数&quot;">​</a></h2><p>以下参数用于试运行起点，不是最终值：</p><table tabindex="0"><thead><tr><th>区域</th><th>自动开灯</th><th style="text-align:right;">无人等待</th><th style="text-align:right;">手动覆盖</th></tr></thead><tbody><tr><td>独立办公室</td><td>有人且照度不足</td><td style="text-align:right;">10 分钟</td><td style="text-align:right;">2 小时或直到无人</td></tr><tr><td>A大厅开放区</td><td>有人且照度不足，按子区开启</td><td style="text-align:right;">15 分钟，先降亮度再关闭</td><td style="text-align:right;">2 小时或场景结束</td></tr><tr><td>D会议室</td><td>有人且照度不足；预约只预备、不直接开灯</td><td style="text-align:right;">10 分钟</td><td style="text-align:right;">当前会议期间</td></tr><tr><td>餐厅</td><td>就餐/清洁时段且有人</td><td style="text-align:right;">15 分钟</td><td style="text-align:right;">当前场景期间</td></tr><tr><td>走廊/电梯厅</td><td>相邻区域有人时提前点亮</td><td style="text-align:right;">3～5 分钟</td><td style="text-align:right;">30 分钟</td></tr><tr><td>卫生间</td><td>检测到人员</td><td style="text-align:right;">5 分钟；风机额外延时</td><td style="text-align:right;">30 分钟</td></tr><tr><td>机房</td><td>默认手动开启</td><td style="text-align:right;">30 分钟</td><td style="text-align:right;">直到手动关闭</td></tr></tbody></table><p>存在传感器的保持时间、照度阈值和窗帘位置必须在两周试点期间调校。不要直接照搬设备出厂默认值。</p><h2 id="规则模板" tabindex="-1">规则模板 <a class="header-anchor" href="#规则模板" aria-label="Permalink to &quot;规则模板&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>场景名称</td><td>如：D会议室进入演示模式</td></tr><tr><td>触发条件</td><td>人体存在、预约开始、墙面开关、时间段</td></tr><tr><td>执行动作</td><td>灯光、窗帘、空调、屏幕、通知</td></tr><tr><td>抑制条件</td><td>手动覆盖、清扫模式、设备维护、传感器离线</td></tr><tr><td>安全边界</td><td>电机互锁、消防独立、手动优先、设备保护</td></tr><tr><td>回退机制</td><td>平台/网络故障时，实体开关仍可用</td></tr><tr><td>退出条件</td><td>时间结束、人员离开、人工取消、指标恢复</td></tr><tr><td>测试证据</td><td>测试日期、人员与环境条件、结果、关联 Issue</td></tr></tbody></table><h2 id="自动化通用约束" tabindex="-1">自动化通用约束 <a class="header-anchor" href="#自动化通用约束" aria-label="Permalink to &quot;自动化通用约束&quot;">​</a></h2><ol><li>单个传感器离线时不得直接判定“无人”；使用最后状态、相邻传感器或保守超时。</li><li>用户手动操作必须产生可见反馈，并记录覆盖开始与结束时间。</li><li>窗帘连续动作之间设置保护间隔，开与关输出必须硬件或软件互锁。</li><li>空调只调整模式和设定值，不使用频繁断电实现节能。</li><li>摄像头不得用于卫生间或以工位行为分析替代普通存在传感器。</li><li>关键告警必须同时具备本地声光或独立保护，平台通知只作为补充。</li></ol><h2 id="验收测试" tabindex="-1">验收测试 <a class="header-anchor" href="#验收测试" aria-label="Permalink to &quot;验收测试&quot;">​</a></h2><ul><li>[ ] 平台在线时，墙面开关、传感器、网页和场景控制均符合优先级。</li><li>[ ] Home Assistant 停机后，所有灯和窗帘仍可现场操作。</li><li>[ ] IoT 网络中断后，不出现灯光反复开关、窗帘持续动作或空调异常启停。</li><li>[ ] 每个区域连续办公半天，无人员静坐导致的误关灯。</li><li>[ ] 手动覆盖期间自动规则不会抢回控制权，覆盖结束后能恢复自动模式。</li><li>[ ] 窗帘连续执行开、停、关和断电恢复测试，无正反转同时输出。</li><li>[ ] 下班、加班、清扫、节假日和临时活动均有明确退出方式。</li><li>[ ] 告警包含设备、房间、时间、当前值和处理建议，并能确认关闭。</li></ul><div class="warning custom-block"><p class="custom-block-title">先测试再上线</p><p>自动化第一次启用时应设定不少于两周的观察期，先记录建议动作，再逐步开放自动执行。涉及门禁、消防、燃气、应急照明和人身安全的系统不得由普通自动化规则直接控制。</p></div>',19)])])}const b=d(e,[["render",l]]);export{m as __pageData,b as default};
